contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint init, uint amount, bool doRevertAddr) public payable {
        require(init > 0);
        require(address(this).balance >= init + amount);

        // Fund c through its public surface: Command forwards value to adr.
        c.Command{value: init}(address(c), "");

        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;

        // Adversary address: either this contract (accepts Ether) or a fresh address.
        address adr = doRevertAddr ? address(0xDeaD) : address(this);

        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint thisAfter = address(this).balance;

        if (doRevertAddr) {
            // plain-address target cannot receive, so it must revert and state must be unchanged
            assert(reverted && balAfter == balBefore && thisAfter == thisBefore);
        } else if (amount >= balBefore) {
            // active branch: adr receives balance+value, c is emptied, we gain exactly that
            assert(balAfter == 0 && thisAfter == thisBefore + balBefore + amount);
        } else {
            // inactive branch: nothing changes
            assert(balAfter == balBefore && thisAfter == thisBefore);
        }
    }

    receive() external payable {}
}

