contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, address adr) public payable {
        // Avoid solver-level balance overflow artifacts.
        require(amount < 2**96);
        // The deciding branch of multiplicate requires msg.value >= balance.
        require(amount >= address(c).balance);
        bool reverted;
        // If amount > 0, multiplicate tries to transfer
        // (balance + msg.value) while its actual balance is only
        // (prior balance + msg.value); the transfer exceeds the balance
        // (by the prior balance portion being double-counted) and reverts.
        // If amount == 0, the transfer amount equals the actual balance,
        // so multiplicate succeeds and pays out exactly the full balance.
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (amount > 0));
    }
    receive() external payable {}
}

